const existing = $input.all().map(function (i) { return i.json; });
if (existing.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + existing.length + ' rows - refusing to append'); }

let maxN = 0;
for (const r of existing) {
  const id = String(r.deal_id == null ? '' : r.deal_id).trim();
  if (id.charAt(0) === 'D') {
    const n = parseInt(id.slice(1), 10);
    if (!isNaN(n) && n > maxN) { maxN = n; }
  }
}
if (maxN === 0) { throw new Error('ABORT: could not determine max deal_id'); }

const seen = {};
for (const r of existing) {
  const k = String(r.startup == null ? '' : r.startup).trim().toLowerCase() + '||' + String(r.investor == null ? '' : r.investor).trim().toLowerCase();
  seen[k] = true;
}

const out = [];
let n = maxN;
let skipped = 0;
for (const inv of Object.keys(DATA)) {
  const email = DATA[inv].e;
  for (const row of DATA[inv].m) {
    const startup = row[0], owner = row[1], score = row[2], due = row[3];
    const key = startup.trim().toLowerCase() + '||' + inv.trim().toLowerCase();
    if (seen[key]) { skipped++; continue; }
    seen[key] = true;
    n++;
    let pad = String(n);
    while (pad.length < 5) { pad = '0' + pad; }
    out.push({ json: {
      deal_id: 'D' + pad,
      startup: startup,
      owner: owner,
      investor: inv,
      email: email,
      cc: '',
      priority: score,
      deal_shared: 'No',
      next_action: 'Initial',
      next_due: due,
      notes: (score >= 85 ? 'Very High' : 'High') + ' match (' + score + ')'
    }});
  }
}

if (out.length === 0) { throw new Error('ABORT: 0 new rows - all pairs already exist (skipped ' + skipped + ')'); }
